// Claude's review tests for A13: resolveReply fills templates when the mock asks. agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { resolveReply } from './reply';
import type { Mock } from '../core/types';

function mock(extra: Partial<Mock> = {}): Mock {
  return {
    id: 'm',
    enabled: true,
    method: 'ANY',
    urlPattern: '/api/users/:id',
    response: { status: 201, headers: { 'x-a': '1' }, body: '{"id":"{{params.id}}"}', bodyEncoding: 'text', delayMs: 5 },
    source: 'manual',
    createdAt: 0,
    ...extra,
  };
}

const facts = { method: 'GET', url: 'http://a.test/api/users/9' };

describe('resolveReply with templates', () => {
  it('fills the body when templates is on, keeping status, headers and delay', async () => {
    const r = await resolveReply(undefined, mock({ templates: true }), facts);
    expect(r.response).toEqual({ status: 201, headers: { 'x-a': '1' }, body: '{"id":"9"}', bodyEncoding: 'text', delayMs: 5 });
    expect(r.error).toBeUndefined();
  });
  it('leaves the body alone when templates is off or absent', async () => {
    expect((await resolveReply(undefined, mock({ templates: false }), facts)).response.body).toBe('{"id":"{{params.id}}"}');
    expect((await resolveReply(undefined, mock(), facts)).response.body).toBe('{"id":"{{params.id}}"}');
  });
  it('never fills a base64 body', async () => {
    const m = mock({ templates: true, response: { status: 200, headers: {}, body: 'e3twYXJhbXMuaWR9fQ==', bodyEncoding: 'base64', delayMs: 0 } });
    expect((await resolveReply(undefined, m, facts)).response.body).toBe('e3twYXJhbXMuaWR9fQ==');
  });
  it('does not change the mock', async () => {
    const m = mock({ templates: true });
    await resolveReply(undefined, m, facts);
    expect(m.response.body).toBe('{"id":"{{params.id}}"}');
  });
});
